void applyToneMapping(float shift, float smooth) {
    const float shift_min = 0.25f;
    const float shift_max = 8.0f;
    const float smooth_min = 0.0f;
    const float smooth_max = 1.0f;

    // Clamp shift and smooth to their respective ranges
    float clampedShift = std::clamp(shift, shift_min, shift_max);
    float clampedSmooth = std::clamp(smooth, smooth_min, smooth_max);

    const int TBLN = 256;
    float *lut = new float[TBLN];

    // Compute the LUT based on the clamped shift value
    for (int i = 0; i < TBLN; ++i) {
        float x = static_cast<float>(i) / static_cast<float>(TBLN - 1);
        if (clampedShift >= 1.0f) {
            // Linear scaling
            lut[i] = x * clampedShift;
        } else {
            // Cubic function
            float x_cubed = x * x * x;
            lut[i] = x_cubed + (1.0f - x_cubed) * (1.0f - clampedShift);
        }
    }

    // Apply the LUT to each pixel in the image data
    for (size_t y = 0; y < C->imageHeight; ++y) {
        for (size_t x = 0; x < C->imageWidth; ++x) {
            float pixelValue = C->imageData[y][x];
            float mappedValue = lut[static_cast<int>(pixelValue * static_cast<float>(TBLN - 1))];
            C->imageData[y][x] = mappedValue;
        }
    }

    // Update the maximum data values based on the LUT
    float maxLutValue = *std::max_element(lut, lut + TBLN);
    C->maxDataValue = maxLutValue;

    // Free the allocated memory for the LUT
    delete[] lut;
}

void apply_tone_mapping(float shift, float smooth) {
    // Clamp shift and smooth to their valid ranges
    shift = std::clamp(shift, 0.25f, 8.0f);
    smooth = std::clamp(smooth, 0.0f, 1.0f);

    // Allocate lookup table
    const int TBLN = 256;
    float *lut = new float[TBLN];

    // Compute lookup table
    for (int i = 0; i < TBLN; ++i) {
        float x = static_cast<float>(i) / (TBLN - 1);
        float y;

        if (shift <= 2.0f) {
            // Linear scaling
            y = x * shift;
        } else {
            // Cubic scaling
            float a = 0.5f * (shift - 2.0f);
            y = x * x * x * (a + 1.0f);
        }

        // Apply smoothing
        y = y * (1.0f - smooth) + x * smooth;

        // Clamp to [0,1]
        y = std::clamp(y, 0.0f, 1.0f);
        lut[i] = y;
    }

    // Apply LUT to image data
    for (int i = 0; i < C->data_size; ++i) {
        int val = C->data[i];
        C->data[i] = static_cast<int>(lut[val] * 255.0f);
    }

    // Update maximum data values in context
    C->max_data = 0;
    for (int i = 0; i < C->data_size; ++i) {
        C->max_data = std::max(C->max_data, C->data[i]);
    }

    // Free LUT memory
    delete[] lut;
}

void applyToneMapping(float shift, float smooth) {
    // Limit shift and smooth to their respective ranges
    shift = std::clamp(shift, 0.25f, 8.0f);
    smooth = std::clamp(smooth, 0.0f, 1.0f);

    const int TBLN = 256;
    float* lut = new float[TBLN];

    // Compute the lookup table based on shift value
    for (int i = 0; i < TBLN; ++i) {
        float in = static_cast<float>(i) / 255.0f;
        if (shift == 1.0f) {
            // Linear scaling when shift is 1.0
            lut[i] = in;
        } else {
            // Cubic function for other values of shift
            float scaled = in * shift;
            float scaledCubed = scaled * scaled * scaled;
            lut[i] = scaledCubed / (1.0f + (shift - 1.0f) * scaled);
        }
    }

    // Apply LUT to each pixel in the image data
    for (size_t y = 0; y < C.height; ++y) {
        for (size_t x = 0; x < C.width; ++x) {
            for (size_t c = 0; c < 3; ++c) {
                float pixelValue = C.imageData[y][x][c];
                int index = static_cast<int>(pixelValue * 255.0f);
                pixelValue = lut[index];
                C.imageData[y][x][c] = std::clamp(pixelValue, 0.0f, 1.0f);
            }
        }
    }

    // Update maximum data values in the context object
    for (int i = 0; i < TBLN; ++i) {
        if (lut[i] > C.maxDataValue)
            C.maxDataValue = lut[i];
    }

    // Free the allocated memory for the LUT
    delete[] lut;
}

void applyToneMapping(float shift, float smooth) {
  // Clamp shift and smooth to their valid ranges
  float clampedShift = std::clamp(shift, 0.25f, 8.0f);
  float clampedSmooth = std::clamp(smooth, 0.0f, 1.0f);

  // Allocate and compute the LUT
  const int TBLN = 256;
  float* lut = new float[TBLN];
  for (int i = 0; i < TBLN; ++i) {
    float val = static_cast<float>(i) / static_cast<float>(TBLN - 1);
    float scaled = val * clampedShift;
    if (clampedShift <= 1.0f) {
      // Linear scaling
      lut[i] = scaled;
    } else {
      // Cubic scaling
      float mapped = scaled / (scaled + clampedSmooth * (1.0f - scaled));
      lut[i] = mapped;
    }
  }

  // Apply the LUT to each pixel in image data
  for (size_t y = 0; y < C->imageHeight; ++y) {
    for (size_t x = 0; x < C->imageWidth; ++x) {
      int index = y * C->imageWidth + x;
      float pixelVal = C->imageData[index];
      pixelVal = lut[static_cast<int>(pixelVal * (TBLN - 1))];
      C->imageData[index] = pixelVal;
    }
  }

  // Update max data values in context object
  C->maxDataValue = lut[TBLN - 1];

  // Free the allocated memory
  delete[] lut;
}

void apply_tone_mapping(float shift, float smooth) {
    // Clamp the shift and smooth values to their valid ranges
    shift = std::clamp(shift, 0.25f, 8.0f);
    smooth = std::clamp(smooth, 0.0f, 1.0f);

    // Allocate the LUT
    const int TBLN = 256;
    float lut[TBLN];

    // Compute the LUT based on the shift parameter
    if (shift == 1.0f) {
        // Linear scaling when shift is 1.0
        for (int i = 0; i < TBLN; ++i) {
            lut[i] = static_cast<float>(i) / 255.0f;
        }
    } else {
        // Cubic scaling for other shift values
        for (int i = 0; i < TBLN; ++i) {
            float x = static_cast<float>(i) / 255.0f;
            float x_shifted = std::pow(x, shift);
            lut[i] = x_shifted / (1.0f + smooth * (1.0f - x_shifted));
        }
    }

    // Apply the LUT to each pixel in the image data
    for (size_t i = 0; i < C->image_data.size(); ++i) {
        float pixel_value = C->image_data[i];
        int index = static_cast<int>(pixel_value * 255.0f);
        C->image_data[i] = lut[index];
    }

    // Update the maximum data values in the context object
    float max_data_value = 0.0f;
    for (float value : C->image_data) {
        if (value > max_data_value) {
            max_data_value = value;
        }
    }
    C->max_data_value = max_data_value;

    // Free the allocated memory for the LUT
    // No dynamic allocation used, so no explicit freeing needed
}
